<?php
declare(strict_types=1);
function onlineDeviceDefenseOrigin(array $device):array{return array_intersect_key($device,array_flip(['id','abilityId','creatorCharacterId','controllerAccountId','sceneId','layerId','x','y','definition','mark']));}
function onlineDeviceDefenseHealth(PDO $db,array &$records,array $pending,array $token):array{
 if(unitUsesCharacterSheet($token)){$key='character:'.$token['characterId'];$records=array_replace($records,applicationDomainRecords($db,[$key]));$token=synchronizeOnlineCharacterToken($token,$pending[$key]['payload']??applicationDomainPayload($records,$key));}
 return ['hp'=>$token['hp']??0,'maxHp'=>$token['maxHp']??0,'dead'=>onlineTokenIsDead($token,true)];
}
function onlineQueueDeviceDefenseGate(PDO $db,array &$records,array &$pending,array $identity,array $device,string $effectType,array $map,array $targets,string $requestId):?array{
 if(!in_array($effectType,['explosion','beam'],true)||($device['definition']['noDefensePossible']??false)===true&&!applicationIsTrassBeam($device))return null;
 $eventId='device-gate-'.hash('sha256',json_encode([$requestId,$device['id'],$effectType],JSON_THROW_ON_ERROR));$activity=$pending['activity']['payload']??applicationDomainPayload($records,'activity');
 foreach($activity['attackReceipts']??[]as$receipt)if(($receipt['requestId']??'')===$eventId)return $receipt['attack'];
 $rows=[];foreach($targets as$row){if($row['damagePercent']<=0)continue;$token=null;foreach($map['tokens']as$entry)if($entry['id']===$row['tokenId'])$token=$entry;if($token===null)continue;$health=onlineDeviceDefenseHealth($db,$records,$pending,$token);if($health['maxHp']<=0||$health['dead'])continue;$rows[]=[...$row,'token'=>$token,'health'=>$health];}
 if(count($rows)>100||count($activity['pendingAttacks']??[])>=XAR_PENDING_ATTACK_MAXIMUM||count($activity['attackReceipts']??[])>=XAR_ATTACK_RECEIPT_MAXIMUM)throw new RuntimeException('La file des décisions de combat est pleine.',429);
 $rolled=$effectType==='beam'?['total'=>$device['mana']]:onlineRollFormula($device['definition']['damageFormula']);
 if($effectType==='explosion'){$damageRoll=onlineRollEntry(['id'=>'mechanics-authority','display_name'=>$device['name'],'effective_mode'=>'gm','permanent_role'=>'gm'],$rolled,$device['name'].' · Explosion',$device['name']);$damageRoll['visibility']='gm';$damageRoll['revealed']=false;onlineAppendAbilityEffectRoll($records,$pending,$damageRoll);}
 if(!$rows&&!($effectType==='beam'&&function_exists('applicationIsTrassBeam')&&applicationIsTrassBeam($device)))return [];
 $now=(int)floor(microtime(true)*1000);$ids=array_column(array_column($rows,'token'),'id');$eligible=[];$parties=[];$damageTargets=[];
 foreach($rows as$row){$token=$row['token'];if($row['health']['hp']>0&&($device['definition']['noDefensePossible']??false)!==true)$eligible[]=$token['id'];$parties[$token['id']]=onlineDefenseParty($db,onlineDeviceOverlayRecords($records,$pending),$token,$map);$damageTargets[]=['tokenId'=>$token['id'],'damagePercent'=>$row['damagePercent'],'amount'=>(int)round($rolled['total']*$row['damagePercent']/100)];}
 $attack=['id'=>'attack-'.randomToken(16),'requestId'=>$eventId,'sceneId'=>$device['sceneId'],'layerId'=>$device['layerId'],'sourceTokenId'=>$device['id'],'deviceOrigin'=>$device['id'],'sourceName'=>$device['name'],'targetTokenId'=>$device['id'],'targetName'=>'Cibles du dispositif','accountId'=>$identity['id'],'attackerRole'=>'gm','playerName'=>$device['name'],'visibility'=>'gm','attackId'=>$device['abilityId'],'attackName'=>$device['name'],'attackKind'=>'ability','status'=>'pending','validationKind'=>'area-gate','areaAnchorOnly'=>true,'damage'=>[],'finalDamage'=>0,'opposed'=>false,'createdAt'=>$now,
  'areaGate'=>['version'=>1,'kind'=>'device-damage','deferred'=>true,'defenseStatId'=>'','targetTokenIds'=>$ids,'defenseEligibleTokenIds'=>$eligible,'sourcePoint'=>['x'=>$device['x'],'y'=>$device['y'],'size'=>$device['size']??1],'sourceParty'=>['unitId'=>unitIdForToken($device)],'targetParties'=>$parties,'deviceDamage'=>['effectType'=>$effectType,'device'=>$device,'origin'=>onlineDeviceDefenseOrigin($device),'rolled'=>$rolled,'targets'=>$damageTargets]]];
 $activity=$pending['activity']['payload']??$activity;$activity['pendingAttacks'][]=$attack;$activity['attackReceipts'][]=['requestId'=>$eventId,'accountId'=>$identity['id'],'requestSignature'=>json_encode([$device['id'],$effectType,$requestId],JSON_THROW_ON_ERROR),'expiresAt'=>$now+XAR_ATTACK_RECEIPT_TTL_MILLISECONDS,'attack'=>$attack];queueOnlineDomainUpsert($pending,$records,'activity',$activity);return $attack;
}
function onlineResolveDeviceDefenseGate(PDO $db,array &$records,array &$pending,array $identity,array $arguments,array $attack):array{
 if(($identity['effective_mode']??$identity['permanent_role']??'')!=='gm')throw new RuntimeException('Seul le MJ choisit les défenses de ce dispositif.',403);
 if(!in_array($arguments['decision']??'',['approve','reject'],true)||($attack['areaGate']['kind']??'')!=='device-damage')throw new RuntimeException('Cette zone n’attend pas cette décision.',400);
 $gate=$attack['areaGate'];$allowed=applicationApprovedAreaDefenseIds([...$gate,'targetTokenIds'=>$gate['defenseEligibleTokenIds']],$arguments['defenseTokenIds']??[]);sort($allowed,SORT_STRING);$signature=json_encode([$arguments['decision'],$allowed],JSON_THROW_ON_ERROR);$activity=$pending['activity']['payload']??applicationDomainPayload($records,'activity');
 if(isset($gate['resolutionSignature'])){if($gate['resolutionSignature']!==$signature)throw new RuntimeException('Cette action a déjà reçu une autre décision.',409);return ['attack'=>$attack,'areaAttacks'=>array_values(array_map(static fn($entry)=>$entry['attack'],array_filter($activity['attackReceipts']??[],static fn($entry)=>($entry['attack']['areaGateParentId']??'')===$attack['id']))),'deduplicated'=>true];}
 $children=[];$snapshot=$gate['deviceDamage'];
 if($arguments['decision']==='approve'){
  $state=onlineDeviceSelectScene(onlineDeviceState($db,$records,$pending),$attack['sceneId'],$attack['layerId']);$device=null;foreach($state['devices']['devices']as$entry)if($entry['id']===$snapshot['device']['id'])$device=$entry;
  if($device===null||dsCanonical(onlineDeviceDefenseOrigin($device))!==dsCanonical($snapshot['origin']))throw new RuntimeException('L’origine du dispositif a changé. Refusez cette demande.',409);
  $targets=[];$eligible=[];foreach($snapshot['targets']as$row){$token=null;foreach($state['map']['tokens']as$entry)if($entry['id']===$row['tokenId'])$token=$entry;if($token===null)throw new RuntimeException('Une cible du dispositif a changé. Refusez cette demande.',409);$health=onlineDeviceDefenseHealth($db,$records,$pending,$token);
   if((!empty($token['hidden'])&&(applicationEffectiveBeamDefinition($snapshot['device'])['affectUnseen']??false)!==true)||$health['dead']||dsCanonical(onlineDefenseParty($db,onlineDeviceOverlayRecords($records,$pending),$token,$state['map']))!==dsCanonical($gate['targetParties'][$row['tokenId']]))throw new RuntimeException('Une cible du dispositif a changé. Refusez cette demande.',409);
   if($health['hp']>0&&($snapshot['device']['definition']['noDefensePossible']??false)!==true)$eligible[]=$row['tokenId'];$targets[]=[...$row,'token'=>$token];
  }
  if(!onlineDefenseIdsEqual($eligible,$gate['defenseEligibleTokenIds']))throw new RuntimeException('Les cibles pouvant se défendre ont changé.',409);
  $initiative=$pending['initiative:'.$attack['sceneId']]['payload']??applicationDomainPayload($records,'initiative:'.$attack['sceneId']);$pendingSlots=($initiative['active']??false)===true?count($allowed):count($targets);
  if(count($activity['pendingAttacks']??[])-1+$pendingSlots>XAR_PENDING_ATTACK_MAXIMUM||count($activity['attackReceipts']??[])+count($targets)>XAR_ATTACK_RECEIPT_MAXIMUM)throw new RuntimeException('La file des attaques est pleine.',429);
  foreach($targets as$row){$child=onlineDeviceAutomaticAttack($db,$records,$pending,$identity,$snapshot['device'],$row['tokenId'],$row['amount'],in_array($row['tokenId'],$allowed,true),'device-hit-'.hash('sha256',json_encode([$attack['id'],$row['tokenId']],JSON_THROW_ON_ERROR)));$child['areaGateParentId']=$attack['id'];$child['areaGateParties']=['sourceUnitId'=>$gate['sourceParty']['unitId'],'targetUnitId'=>$gate['targetParties'][$row['tokenId']]['unitId']];$children[]=$child;
   $activity=$pending['activity']['payload'];foreach($activity['attackReceipts']as&$receipt)if(($receipt['attack']['id']??'')===$child['id'])$receipt['attack']=$child;unset($receipt);foreach($activity['pendingAttacks']as&$entry)if($entry['id']===$child['id'])$entry=$child;unset($entry);queueOnlineDomainUpsert($pending,$records,'activity',$activity);
   if($child['status']==='applied')onlineAppendAppliedDamageAction($db,$records,$pending,$identity,$child);
  }
  if(function_exists('onlineTrassBeamPresentation')){$visual=onlineTrassBeamPresentation($db,$records,$pending,$snapshot['device'],$attack['requestId']);if(isset($visual['delta']))$attack['deviceBeamDelta']=$visual['delta'];}
 }
 $activity=$pending['activity']['payload']??$activity;$gate['resolutionSignature']=$signature;$gate['defenseTokenIds']=$allowed;$attack['areaGate']=$gate;$attack['status']=$arguments['decision']==='approve'?'resolved':'rejected';$attack['resolvedAt']=(int)floor(microtime(true)*1000);$activity['pendingAttacks']=array_values(array_filter($activity['pendingAttacks']??[],static fn($entry)=>$entry['id']!==$attack['id']));foreach($activity['attackReceipts']as&$receipt)if(($receipt['attack']['id']??'')===$attack['id']){$receipt['attack']=$attack;$receipt['areaAttackIds']=array_column($children,'id');$receipt['expiresAt']=$attack['resolvedAt']+XAR_ATTACK_RECEIPT_TTL_MILLISECONDS;}unset($receipt);queueOnlineDomainUpsert($pending,$records,'activity',$activity);
 onlineAppendPlayerAction($db,$records,$pending,$identity,$attack['sceneId'],['kind'=>'attack','attackId'=>$attack['id'],'characterName'=>$attack['sourceName'],'summary'=>$attack['sourceName'].' · '.$attack['attackName'],'detail'=>$arguments['decision']==='approve'?'Défenses du dispositif validées par le MJ':'Résolution des dégâts du dispositif refusée']);
 return ['attack'=>$attack,'areaAttacks'=>$children,'deduplicated'=>false];
}
